1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strconv"
10		"unicode/utf8"
11	)
12	
13	// EvalReason is the machine-readable outcome of a flag evaluation.
14	type EvalReason string
15	
16	const (
17		EvalDisabled EvalReason = "disabled"
18		EvalRule     EvalReason = "rule"
19		EvalDefault  EvalReason = "default"
20	)
21	
22	// Condition is one predicate over an evaluation context.
23	type Condition struct {
24		Attribute string
25		Op        string
26		// strVal 用于 eq；inVal 用于 in（至少一项）。
27		strVal string
28		inVal  []string
29	}
30	
31	// Rule groups conditions that must all hold; on match the flag takes Value.
32	type Rule struct {
33		ID         string
34		Value      bool
35		Conditions []Condition
36	}
37	
38	// Flag is one feature toggle with its default and ordered rules.
39	type Flag struct {
40		Key     string
41		Enabled bool
42		Default bool
43		Rules   []Rule
44	}
45	
46	// Config is a validated feature flag configuration.
47	type Config struct {
48		Flags []Flag
49	}
50	
51	// EvalResult is the deterministic outcome of evaluating one flag.
52	type EvalResult struct {
53		Key    string     `json:"key"`
54		Value  bool       `json:"value"`
55		Reason EvalReason `json:"reason"`
56		RuleID *string    `json:"ruleId"`
57	}
58	
59	// Equals reports whether two evaluation results are identical.
60	func (r EvalResult) Equals(other EvalResult) bool {
61		if r.Key != other.Key || r.Value != other.Value || r.Reason != other.Reason {
62			return false
63		}
64		if (r.RuleID == nil) != (other.RuleID == nil) {
65			return false
66		}
67		if r.RuleID != nil && *r.RuleID != *other.RuleID {
68			return false
69		}
70		return true
71	}
72	
73	// ConditionExplanation 记录单个条件在给定上下文上的判断：属性名、比较方式
74	// （eq/in）、配置中的比较值、上下文实际值以及条件是否成立。属性缺失时
75	// Missing 为 true 且 ActualValue 为 nil——与显式给出的空字符串
76	// （ActualValue 指向 ""、Missing 为 false）明确区分。
77	type ConditionExplanation struct {
78		Attribute    string `json:"attribute"`
79		Op           string `json:"op"`
80		CompareValue any    `json:"compareValue"`
81		// ActualValue 为上下文实际值；属性缺失时为 nil 并把 Missing 置为 true。
82		ActualValue *string `json:"actualValue"`
83		Missing     bool    `json:"missing"`
84		Match       bool    `json:"match"`
85	}
86	
87	// RuleExplanation 记录一条被考虑过的规则：规则编号、是否整体命中以及它的
88	// 全部条件逐条判断结果（即使规则在首个失败条件后已确定不命中，其余条件的
89	// 判断也照样给出）。
90	type RuleExplanation struct {
91		RuleID     string                 `json:"ruleId"`
92		Match      bool                   `json:"match"`
93		Conditions []ConditionExplanation `json:"conditions"`
94	}
95	
96	// EvalExplanation 是解释模式附加在结果对象上的判断过程。Outcome 用一句话
97	// 说明最终结果的依据；Rules 按配置顺序列出实际考虑过的规则，到第一条全部
98	// 条件成立的规则为止（含该规则），开关关闭时为空列表。
99	type EvalExplanation struct {
100		Outcome string            `json:"outcome"`
101		Rules   []RuleExplanation `json:"rules"`
102	}
103	
104	// ExplainedResult 是解释模式的输出：四个既有字段与普通模式逐字一致，
105	// 另带 explanation 判断记录。
106	type ExplainedResult struct {
107		EvalResult
108		Explanation EvalExplanation `json:"explanation"`
109	}
110	
111	// Context is a validated map of attribute names to string values.
112	type Context struct {
113		values map[string]string
114	}
115	
116	// LoadConfig reads and strictly validates a UTF-8 JSON flag config file.
117	// 所有开关都会被完整校验，包括不会被求值或已关闭的开关。
118	func LoadConfig(path string) (*Config, error) {
119		raw, err := os.ReadFile(path)
120		if err != nil {
121			return nil, fmt.Errorf("cannot read config file %q: %w", path, err)
122		}
123		return ParseConfig(raw)
124	}
125	
126	// LoadContext reads and validates a UTF-8 JSON context file.
127	func LoadContext(path string) (*Context, error) {
128		raw, err := os.ReadFile(path)
129		if err != nil {
130			return nil, fmt.Errorf("cannot read context file %q: %w", path, err)
131		}
132		return ParseContext(raw)
133	}
134	
135	// unmarshalStrictJSON 严格解码一个 UTF-8 JSON 文档到 any，并保持与
136	// json.Unmarshal 相同的单文档语义：文档之后只允许空白，不允许第二个值。
137	// 使用 json.Decoder + UseNumber：数字按原文保留为 json.Number，而不是强制
138	// 转成 float64——语法合法但超出浮点范围的数字（如 1e400、由 1 后接 400 个 0
139	// 组成的整数）不应被当成“JSON 无效”，它们是合法的 JSON 数字，由后续的值
140	// 类型检查以所属字段的类型错误报告。
141	func unmarshalStrictJSON(raw []byte) (any, error) {
142		dec := json.NewDecoder(bytes.NewReader(raw))
143		dec.UseNumber()
144		var doc any
145		if err := dec.Decode(&doc); err != nil {
146			return nil, err
147		}
148		// Decoder 本身容忍文档之后的额外 JSON 值，需显式补回 Unmarshal 的严格性。
149		offset := int(dec.InputOffset())
150		var extra any
151		if err := dec.Decode(&extra); err != io.EOF {
152			if err != nil {
153				return nil, err
154			}
155			for offset < len(raw) && isJSONWhitespace(raw[offset]) {
156				offset++
157			}
158			c := byte(0)
159			if offset < len(raw) {
160				c = raw[offset]
161			}
162			return nil, fmt.Errorf("invalid character %q after top-level value", c)
163		}
164		return doc, nil
165	}
166	
167	// isJSONWhitespace 报告 b 是否为 JSON 允许的空白字节。
168	func isJSONWhitespace(b byte) bool {
169		return b == ' ' || b == '\t' || b == '\n' || b == '\r'
170	}
171	
172	// parseJSONDocument 执行配置与上下文两类输入共同维护的文档格式校验，使两份
173	// JSON 对同一组格式规则给出一致的接受结果与错误定位。检查按固定先后顺序报告
174	// 原文中的第一处问题：
175	//  1. 非法 UTF-8 字节——最先检查，不被其后任何错误遮住；
176	//  2. 不能组成完整字符的 \uXXXX 转义（字段名与字符串值同等检查）——先于
177	//     重复字段，避免 encoding/json 把孤立代理项静默替换成 U+FFFD 后误判重复；
178	//  3. 同一对象内的重复字段——先于业务字段问题；
179	//  4. JSON 语法与单文档边界：只接受一个顶层值，完整文档后只允许空白，
180	//     第二个值或其他尾随内容一律拒绝；
181	//  5. 顶层必须是一个 JSON 对象。
182	//
183	// 这一步只判定文档格式：数字一律按原文保留（json.Number），语法合法但超出
184	// 浮点范围的大数字不在此拒绝；具体字段的类型/必填/唯一性属于各自的业务规则，
185	// 由调用方在取得 root 后按配置或上下文的约定继续校验。label 是本文档在错误
186	// 信息中的名字（"config" 或 "context"）。
187	func parseJSONDocument(raw []byte, label string) (map[string]any, error) {
188		if !utf8.Valid(raw) {
189			return nil, fmt.Errorf("%s: file is not valid UTF-8", label)
190		}
191		if err := rejectInvalidUnicodeEscapes(raw, label); err != nil {
192			return nil, err
193		}
194		if err := rejectDuplicateFields(raw, label); err != nil {
195			return nil, err
196		}
197		doc, err := unmarshalStrictJSON(raw)
198		if err != nil {
199			return nil, fmt.Errorf("%s: invalid JSON: %w", label, err)
200		}
201		root, ok := doc.(map[string]any)
202		if !ok {
203			return nil, fmt.Errorf("%s: top level must be a JSON object", label)
204		}
205		return root, nil
206	}
207	
208	// ParseConfig parses a config document from JSON bytes with strict typing.
209	// 文档格式校验由 parseJSONDocument 与 ParseContext 共同维护；这里只继续处理
210	// 配置自身的业务字段（开关、规则、条件与唯一性）。先解析到 any 再逐字段校验，
211	// 以区分“字段缺失”与“显式提供的 false”。
212	func ParseConfig(raw []byte) (*Config, error) {
213		root, err := parseJSONDocument(raw, "config")
214		if err != nil {
215			return nil, err
216		}
217		flagsRaw, present := root["flags"]
218		if !present {
219			return nil, fmt.Errorf("config.flags: field is required")
220		}
221		if flagsRaw == nil {
222			return nil, fmt.Errorf("config.flags: must be an array, got null")
223		}
224		flagsArr, ok := flagsRaw.([]any)
225		if !ok {
226			return nil, fmt.Errorf("config.flags: must be an array")
227		}
228		cfg := &Config{}
229		seenKeys := map[string]int{}
230		for i, fr := range flagsArr {
231			flag, err := parseFlag(fr, i)
232			if err != nil {
233				return nil, err
234			}
235			if prev, dup := seenKeys[flag.Key]; dup {
236				return nil, fmt.Errorf("config.flags[%d].key: duplicate flag key %q (first at flags[%d])", i, flag.Key, prev)
237			}
238			seenKeys[flag.Key] = i
239			cfg.Flags = append(cfg.Flags, flag)
240		}
241		return cfg, nil
242	}
243	
244	// ParseContext parses an attribute-name -> string context object; it may be empty.
245	// 文档格式校验由 parseJSONDocument 与 ParseConfig 共同维护；这里只继续检查
246	// 上下文自身的业务规则：每个顶层属性的值都必须是字符串。
247	func ParseContext(raw []byte) (*Context, error) {
248		root, err := parseJSONDocument(raw, "context")
249		if err != nil {
250			return nil, err
251		}
252		// 语法校验通过后才建立可用属性：值类型检查与属性建立在同一次遍历中完成。
253		return buildContext(raw, root)
254	}
255	
256	// buildContext 按文件原文顺序做一次流式遍历，同时完成顶层属性的值类型检查
257	// 与可用属性的建立：字段名顺序取自令牌流（Go map 的遍历顺序不稳定，不能
258	// 直接 range root，否则同一文件在不同运行中可能报告不同属性），属性值复用
259	// 严格解码得出的 root——同一份上下文的值只解码一次。语法、重复字段与 Unicode
260	// 转义已在此前校验，这里的令牌读取不会再遇到错误。键名使用解码后的文字
261	// （合法的 \uXXXX 转义与直接字符同义；大小写与空白按原样保留）。对象或数组
262	// 值整体算所属顶层属性的一个值，错误不指向其内部成员。
263	func buildContext(raw []byte, root map[string]any) (*Context, error) {
264		dec := json.NewDecoder(bytes.NewReader(raw))
265		// 消费顶层对象的 '{'；语法已由 unmarshalStrictJSON 校验。
266		if _, err := dec.Token(); err != nil {
267			return nil, fmt.Errorf("context: invalid JSON: %w", err)
268		}
269		ctx := &Context{values: make(map[string]string, len(root))}
270		for dec.More() {
271			keyTok, err := dec.Token()
272			if err != nil {
273				return nil, fmt.Errorf("context: invalid JSON: %w", err)
274			}
275			key, _ := keyTok.(string)
276			// 值不再重复解码：RawMessage 只把读取位置推进到下一个字段，
277			// 实际值取自已严格解码的 root。数字（含超出浮点范围的 json.Number）、
278			// 布尔、null、对象、数组都在这里按所属属性报类型错误。
279			var skipped json.RawMessage
280			if err := dec.Decode(&skipped); err != nil {
281				return nil, fmt.Errorf("context: invalid JSON: %w", err)
282			}
283			s, ok := root[key].(string)
284			if !ok {
285				return nil, fmt.Errorf("%s: value must be a string", appendFieldPath("context", key))
286			}
287			ctx.values[key] = s
288		}
289		return ctx, nil
290	}
291	
292	// Get looks up an attribute; an empty string is a legal value.
293	func (c *Context) Get(attribute string) (string, bool) {
294		if c == nil {
295			return "", false
296		}
297		v, ok := c.values[attribute]
298		return v, ok
299	}
300	
301	// Find returns the flag with the given key, or nil if absent.
302	func (c *Config) Find(key string) *Flag {
303		if c == nil {
304			return nil
305		}
306		for i := range c.Flags {
307			if c.Flags[i].Key == key {
308				return &c.Flags[i]
309			}
310		}
311		return nil
312	}
313	
314	// evaluate 是普通模式与解释模式共同维护的唯一定案路径：关闭固定 false
315	// （reason=disabled），不使用默认值或规则；启用后取首条所有条件均成立的规则的
316	// value（即使它返回 false 也立即定案，后续规则不再考虑）；无匹配取 default。
317	// 求值不依赖时间、随机数或 map 遍历顺序。keepRecord 为 false（普通模式）时只
318	// 算出定案结果，不整理任何判断记录；为 true（解释模式）时把定案所依据的逐条
319	// 条件判断与规则遍历过程一并记录在返回值中。两种模式共用这里的规则优先级与
320	// 条件比较，对同一份配置与上下文不可能给出不同判断。
321	func (f *Flag) evaluate(ctx *Context, keepRecord bool) evaluation {
322		if !f.Enabled {
323			ev := evaluation{
324				result: EvalResult{Key: f.Key, Value: false, Reason: EvalDisabled, RuleID: nil},
325			}
326			if keepRecord {
327				ev.outcome = "flag is disabled; result is fixed to false without evaluating rules or the default"
328				ev.rules = []RuleExplanation{}
329			}
330			return ev
331		}
332		// considered 按配置顺序收集定案前实际考虑过的规则，到第一条全部条件成立的
333		// 规则为止（含该规则）；无规则或全部不命中时为空列表而非 nil。仅解释模式
334		// 收集，普通模式不为判断记录分配任何空间。
335		var considered []RuleExplanation
336		if keepRecord {
337			considered = make([]RuleExplanation, 0, len(f.Rules))
338		}
339		for i := range f.Rules {
340			rule := &f.Rules[i]
341			var matched bool
342			if keepRecord {
343				re := rule.evaluate(ctx)
344				considered = append(considered, re)
345				matched = re.Match
346			} else {
347				matched = rule.matches(ctx)
348			}
349			if matched {
350				id := rule.ID
351				ev := evaluation{
352					result: EvalResult{Key: f.Key, Value: rule.Value, Reason: EvalRule, RuleID: &id},
353					rules:  considered,
354				}
355				if keepRecord {
356					ev.outcome = fmt.Sprintf("first matching rule %q decides the result; later rules are not considered", rule.ID)
357				}
358				return ev
359			}
360		}
361		ev := evaluation{
362			result: EvalResult{Key: f.Key, Value: f.Default, Reason: EvalDefault, RuleID: nil},
363			rules:  considered,
364		}
365		if keepRecord {
366			ev.outcome = "no rule matched; the flag default is used"
367		}
368		return ev
369	}
370	
371	// evaluation 是一次求值的产出：定案的四字段结果，以及仅解释模式才填写的
372	// 一句话依据与按配置顺序考虑过的规则判断记录。普通模式只用 result，outcome
373	// 与 rules 保持零值，不为它们付出整理与复制开销。
374	type evaluation struct {
375		result  EvalResult
376		outcome string
377		rules   []RuleExplanation
378	}
379	
380	// Evaluate deterministically evaluates a flag against a context；定案规则与
381	// 解释模式统一由 evaluate 维护，本入口只取最终结果，不生成判断记录。
382	func (f *Flag) Evaluate(ctx *Context) EvalResult {
383		return f.evaluate(ctx, false).result
384	}
385	
386	// EvaluateExplain 与 Evaluate 走同一条 evaluate 定案路径（关闭固定 false、
387	// 首条全部条件成立的规则决定结果、否则取 default），并额外把该路径产出的判断
388	// 记录作为 explanation：每条在定案前被考虑过的规则都给出 id、是否命中与全部
389	// 条件的逐条判断；第一条命中的规则（即使返回 false）也计入并立即停止，其后的
390	// 规则不出现。开关关闭时不评估任何规则，解释中的规则列表为空，结果依据只
391	// 说明关闭导致固定 false。
392	func (f *Flag) EvaluateExplain(ctx *Context) ExplainedResult {
393		e := f.evaluate(ctx, true)
394		return ExplainedResult{
395			EvalResult: e.result,
396			Explanation: EvalExplanation{
397				Outcome: e.outcome,
398				Rules:   e.rules,
399			},
400		}
401	}
402	
403	// matches 判断一条规则是否全部条件成立，在首个失败条件处短路。它不产生任何
404	// 判断记录，是普通求值路径使用的轻量入口；条件是否成立与解释模式共用
405	// Condition.compare 这同一份比较逻辑。
406	func (r *Rule) matches(ctx *Context) bool {
407		if len(r.Conditions) == 0 {
408			// 解析阶段已要求规则至少含一个条件，这里只是防御性处理，避免无条件的
409			// 规则被当成命中。
410			return false
411		}
412		for i := range r.Conditions {
413			if !r.Conditions[i].matches(ctx) {
414				return false
415			}
416		}
417		return true
418	}
419	
420	// evaluate 判断一条规则的全部条件并逐条记录判断结果；Match 为所有条件都
421	// 成立。它不会在首个失败条件处短路，因此每个条件的属性、比较值、实际值与
422	// 是否成立都能展示出来，规则整体的命中判断与条件逐条判断共用这一份结果。
423	// 仅供解释模式使用。
424	func (r *Rule) evaluate(ctx *Context) RuleExplanation {
425		re := RuleExplanation{RuleID: r.ID, Match: true, Conditions: make([]ConditionExplanation, 0, len(r.Conditions))}
426		for i := range r.Conditions {
427			ce := r.Conditions[i].evaluate(ctx)
428			re.Conditions = append(re.Conditions, ce)
429			if !ce.Match {
430				re.Match = false
431			}
432		}
433		if len(re.Conditions) == 0 {
434			// 与 matches 相同的防御性处理：无条件的规则不命中。
435			re.Match = false
436		}
437		return re
438	}
439	
440	// matches 判断单个条件是否成立，不产生判断记录。属性缺失一律不成立；其余
441	// 情况交给 compare 这个唯一的比较实现。
442	func (c Condition) matches(ctx *Context) bool {
443		v, present := ctx.Get(c.Attribute)
444		return present && c.compare(v)
445	}
446	
447	// compare 是 eq/in 两类条件唯一的比较实现：给定上下文中的实际值，报告条件
448	// 是否成立。普通模式的 matches 与解释模式的 evaluate 都以它为准，两种模式
449	// 不会各算一套。未知运算符（解析阶段已拒绝，这里防御性处理）一律不成立。
450	func (c Condition) compare(actual string) bool {
451		switch c.Op {
452		case "eq":
453			return actual == c.strVal
454		case "in":
455			for _, candidate := range c.inVal {
456				if actual == candidate {
457					return true
458				}
459			}
460		}
461		return false
462	}
463	
464	// evaluate 判断单个条件并记录属性名、比较方式、配置比较值、上下文实际值与
465	// 是否成立；是否成立由 compare 这同一份比较逻辑得出，与普通模式不再各算一遍。
466	// 属性缺失用 Missing=true、ActualValue=nil 表示，绝不与显式空字符串
467	// （ActualValue 指向 ""）混淆。仅供解释模式使用。
468	func (c Condition) evaluate(ctx *Context) ConditionExplanation {
469		ce := ConditionExplanation{Attribute: c.Attribute, Op: c.Op}
470		switch c.Op {
471		case "eq":
472			ce.CompareValue = c.strVal
473		case "in":
474			// 复制一份，避免外部切片与解释记录共享底层数组。
475			list := make([]string, len(c.inVal))
476			copy(list, c.inVal)
477			ce.CompareValue = list
478		default:
479			// 解析阶段已拒绝未知运算符，防御性处理。
480			ce.CompareValue = nil
481		}
482		v, present := ctx.Get(c.Attribute)
483		if !present {
484			ce.Missing = true
485			ce.Match = false
486			return ce
487		}
488		ce.ActualValue = &v
489		ce.Match = c.compare(v)
490		return ce
491	}
492	
493	// MarshalResult renders the result as a single compact JSON object.
494	func MarshalResult(r EvalResult) ([]byte, error) {
495		var buf bytes.Buffer
496		enc := json.NewEncoder(&buf)
497		enc.SetEscapeHTML(false)
498		if err := enc.Encode(r); err != nil {
499			return nil, err
500		}
501		return bytes.TrimRight(buf.Bytes(), "\n"), nil
502	}
503	
504	// MarshalExplain renders an explained result as a single compact JSON object:
505	// key/value/reason/ruleId 四个字段与 MarshalResult 逐字一致，其后追加
506	// explanation 判断记录；列表中的空字符串、重复成员与次序原样保留，不裁剪
507	// 空白、不合并大小写。
508	func MarshalExplain(r ExplainedResult) ([]byte, error) {
509		var buf bytes.Buffer
510		enc := json.NewEncoder(&buf)
511		enc.SetEscapeHTML(false)
512		if err := enc.Encode(r); err != nil {
513			return nil, err
514		}
515		return bytes.TrimRight(buf.Bytes(), "\n"), nil
516	}
517	
518	// --- strict parsing helpers -------------------------------------------------
519	
520	// isSimpleFieldName 报告字段名是否走点号连接：以 ASCII 字母或下划线开头，
521	// 其后只能含 ASCII 字母、数字、下划线。其他任何名字（含点号、方括号、空白、
522	// 空名、非 ASCII 字符）都改用方括号包住的 JSON 字符串定位，如
523	// context["user.name"]、context[""]。
524	func isSimpleFieldName(name string) bool {
525		if name == "" {
526			return false
527		}
528		for i := 0; i < len(name); i++ {
529			c := name[i]
530			// 非 ASCII 字节（UTF-8 续字节或首字节）一律不满足“仅 ASCII”的要求。
531			if c >= 0x80 {
532				return false
533			}
534			ok := ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') || c == '_'
535			if i > 0 {
536				ok = ok || ('0' <= c && c <= '9')
537			}
538			if !ok {
539				return false
540			}
541		}
542		return true
543	}
544	
545	// appendFieldPath 在父位置后接上一个字段：简单字段名用点号连接，其余字段名
546	// 用方括号包住一个 JSON 字符串，引号、反斜杠与控制字符按 JSON 转义显示
547	// （Marshal 对 U+2028/U+2029 也会转义，但普通可见 Unicode 保持原样）。
548	// 名字按 JSON 解码后的文字传入，因此直接字符与合法 \uXXXX 转义得到同一位置。
549	func appendFieldPath(parent, name string) string {
550		if isSimpleFieldName(name) {
551			return parent + "." + name
552		}
553		return parent + "[" + jsonQuote(name) + "]"
554	}
555	
556	// jsonQuote 把字符串渲染为带双引号的 JSON 字符串字面量：引号、反斜杠与控制
557	// 字符按 JSON 转义（U+2028/U+2029 也会转义，避免定位文字被行分隔符拆行），
558	// 其余可见字符（含 <>& 与非 ASCII 文字）保持原样。
559	func jsonQuote(s string) string {
560		var buf bytes.Buffer
561		enc := json.NewEncoder(&buf)
562		enc.SetEscapeHTML(false)
563		if err := enc.Encode(s); err != nil {
564			// 不会发生：string 的 JSON 编码没有失败路径；保留一个确定的退路。
565			return strconv.Quote(s)
566		}
567		return string(bytes.TrimRight(buf.Bytes(), "\n"))
568	}
569	
570	// jsonFrame 是 JSON 原文遍历中一个对象或数组的层级状态。重复字段检查与非法
571	// Unicode 转义检查共用这一份层级与位置定义，调整错误定位时只需改这一处。
572	type jsonFrame struct {
573		path   string // 容器自身的完整位置，如 config.flags[0].rules[1]
574		object bool
575		// keys 记录本对象已声明的字段名（按解码后的字符串），仅重复字段检查使用；
576		// Unicode 遍历不登记字段，保持 nil。
577		keys map[string]struct{}
578		// lastKey 是对象最近一个字段名，用于拼出字段值的位置。
579		lastKey string
580		// expectKey 标记对象内下一个字符串是否为字段名。
581		expectKey bool
582		// nextIndex 是数组下一个元素的下标。
583		nextIndex int
584	}
585	
586	// jsonPathTracker 是两类 JSON 检查共用的对象层级、数组位置与字段路径状态机。
587	// label 是根容器的位置前缀（"config" 或 "context"）。
588	type jsonPathTracker struct {
589		label string
590		stack []*jsonFrame
591	}
592	
593	func newJSONPathTracker(label string) *jsonPathTracker {
594		return &jsonPathTracker{label: label}
595	}
596	
597	func (t *jsonPathTracker) top() *jsonFrame {
598		return t.stack[len(t.stack)-1]
599	}
600	
601	// childPath 拼出栈顶容器内下一个子值的位置：对象的字段值按 appendFieldPath
602	// 规则连接（简单名用点号，其余用方括号 JSON 字符串），数组元素用 [下标]。
603	func (t *jsonPathTracker) childPath() string {
604		top := t.top()
605		if top.object {
606			return appendFieldPath(top.path, top.lastKey)
607		}
608		return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
609	}
610	
611	// beginContainer 在遇到 '{' 或 '[' 时压入新容器，返回新容器的完整位置。
612	func (t *jsonPathTracker) beginContainer(object bool) string {
613		path := t.label
614		if len(t.stack) > 0 {
615			path = t.childPath()
616		}
617		t.stack = append(t.stack, &jsonFrame{path: path, object: object, expectKey: object})
618		return path
619	}
620	
621	// endContainer 在遇到 '}' 或 ']' 时弹出容器，并把整个容器计为父容器中
622	// 一个已完成的值。
623	func (t *jsonPathTracker) endContainer() {
624		if len(t.stack) > 0 {
625			t.stack = t.stack[:len(t.stack)-1]
626		}
627		t.endValue()
628	}
629	
630	// atKey 报告下一个字符串是否应按对象字段名处理。
631	func (t *jsonPathTracker) atKey() bool {
632		return len(t.stack) > 0 && t.top().object && t.top().expectKey
633	}
634	
635	// currentPath 返回当前容器自身的位置（字段名报错时指向所属对象）；
636	// 栈为空时返回根标签。
637	func (t *jsonPathTracker) currentPath() string {
638		if len(t.stack) == 0 {
639			return t.label
640		}
641		return t.top().path
642	}
643	
644	// valuePath 拼出下一个字符串值（字段值或数组元素）的位置，但不改变状态。
645	func (t *jsonPathTracker) valuePath() string {
646		if len(t.stack) == 0 {
647			return t.label
648		}
649		return t.childPath()
650	}
651	
652	// endValue 在一个字段值或数组元素完成后调用：对象回到等待字段名的状态，
653	// 数组推进元素下标。
654	func (t *jsonPathTracker) endValue() {
655		if len(t.stack) == 0 {
656			return
657		}
658		top := t.top()
659		if top.object {
660			top.expectKey = true
661		} else {
662			top.nextIndex++
663		}
664	}
665	
666	// noteKey 登记一个已解码的对象字段名：更新字段路径状态，并在同一对象内第二次
667	// 声明同名字段时返回重复字段错误。
668	func (t *jsonPathTracker) noteKey(name string) error {
669		top := t.top()
670		if top.keys == nil {
671			top.keys = make(map[string]struct{})
672		}
673		if _, dup := top.keys[name]; dup {
674			return fmt.Errorf("%s: duplicate field %s", appendFieldPath(top.path, name), jsonQuote(name))
675		}
676		top.keys[name] = struct{}{}
677		top.lastKey = name
678		top.expectKey = false
679		return nil
680	}
681	
682	// setKey 在不做重复检查的遍历（Unicode 扫描）中记录一个成功解码的字段名，
683	// 仅维护字段值路径所需的状态。
684	func (t *jsonPathTracker) setKey(name string) {
685		top := t.top()
686		top.lastKey = name
687		top.expectKey = false
688	}
689	
690	// noteInvalidKey 在字段名无法解码（属于 JSON 语法错误）时仅推进键值状态：
691	// 不覆盖已记录的字段名；语法错误留给后续严格 JSON 解码报告。
692	func (t *jsonPathTracker) noteInvalidKey() {
693		t.top().expectKey = false
694	}
695	
696	// rejectDuplicateFields 按文件原文顺序扫描 JSON 令牌流，拒绝任何在同一对象内
697	// 重复声明的字段名。字段名按解码后的字符串比较（"enabled" 与 "énabled"
698	// 同名），大小写不同仍是不同字段，名字中的空白不裁剪。检查覆盖所有对象，
699	// 包括附加字段里嵌套的对象；数组元素不属于这一检查。label 是根对象的位置
700	// 前缀（"config" 或 "context"）。对象层级、数组下标与字段路径由
701	// jsonPathTracker 统一维护。JSON 语法错误不在此报告（令牌流失效即停止），
702	// 留给严格 JSON 解码。
703	func rejectDuplicateFields(raw []byte, label string) error {
704		dec := json.NewDecoder(bytes.NewReader(raw))
705		// UseNumber：数字以 json.Number 令牌返回而不转 float64，否则超出浮点范围
706		// 的合法数字（如 1e400）会让令牌流提前报错并中止，遮住其后的重复字段。
707		dec.UseNumber()
708		tracker := newJSONPathTracker(label)
709		for {
710			tok, err := dec.Token()
711			if err != nil {
712				// io.EOF 或语法错误；语法错误由后续严格 JSON 解码报告。
713				break
714			}
715			switch t := tok.(type) {
716			case json.Delim:
717				switch t {
718				case '{':
719					tracker.beginContainer(true)
720				case '[':
721					tracker.beginContainer(false)
722				case '}', ']':
723					tracker.endContainer()
724				}
725			case string:
726				if tracker.atKey() {
727					if err := tracker.noteKey(t); err != nil {
728						return err
729					}
730				} else {
731					tracker.endValue()
732				}
733			default:
734				tracker.endValue()
735			}
736		}
737		return nil
738	}
739	
740	// rejectInvalidUnicodeEscapes 按文件原文顺序扫描 JSON 文本，拒绝任何不能组成
741	// 完整字符的 \uXXXX 转义：孤立的高代理项、孤立的低代理项，以及不完整或顺序
742	// 错误的代理项对。encoding/json 解码时会把这类转义静默替换为 U+FFFD，使非法
743	// 输入与真正的 "�" 被当作相同字符串参与求值，或让字段名在替换后被误判为重复，
744	// 因此必须在解码前按原文拒绝。检查覆盖字段名与所有字符串值（包括规则的比较值、
745	// in 列表元素以及附加字段里的字符串），一个文件有多个问题时报告原文中最先出现
746	// 的一处。label 是根对象的位置前缀（"config" 或 "context"）。对象层级、数组
747	// 下标与字段路径由 jsonPathTracker 统一维护；JSON 语法错误不在此报告，留给
748	// Unmarshal。
749	func rejectInvalidUnicodeEscapes(raw []byte, label string) error {
750		tracker := newJSONPathTracker(label)
751		i := 0
752		for i < len(raw) {
753			c := raw[i]
754			switch {
755			case c == '{' || c == '[':
756				tracker.beginContainer(c == '{')
757				i++
758			case c == '}' || c == ']':
759				tracker.endContainer()
760				i++
761			case c == '"':
762				end := jsonStringEnd(raw, i)
763				contentEnd := end
764				if contentEnd > i+1 && raw[contentEnd-1] == '"' {
765					contentEnd-- // 去掉右引号；未终止的字符串留给严格 JSON 解码报告
766				}
767				content := raw[i+1 : contentEnd]
768				if tracker.atKey() {
769					if bad := findBadUnicodeEscape(content); bad != nil {
770						return fmt.Errorf("%s: field name %q contains invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
771							tracker.currentPath(), string(content), bad.escape, bad.detail)
772					}
773					// 转义已校验合法，解码用于定位路径；失败说明是语法错误，留给严格 JSON 解码。
774					if name, ok := decodeJSONString(raw[i:end]); ok {
775						tracker.setKey(name)
776					} else {
777						tracker.noteInvalidKey()
778					}
779				} else {
780					path := tracker.valuePath()
781					if bad := findBadUnicodeEscape(content); bad != nil {
782						return fmt.Errorf("%s: invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
783							path, bad.escape, bad.detail)
784					}
785					tracker.endValue()
786				}
787				i = end
788			case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ':' || c == ',':
789				i++
790			default:
791				// 数字与 true/false/null 等标量：跳过至下一个结构字符，按一个值计。
792				for i < len(raw) && !isJSONStructural(raw[i]) {
793					i++
794				}
795				tracker.endValue()
796			}
797		}
798		return nil
799	}
800	
801	// decodeJSONString 解码一个完整的 JSON 字符串字面量（含两侧引号）；ok 为 false
802	// 表示字面量本身非法（未终止或转义写法错误等），属于 JSON 语法错误。
803	func decodeJSONString(lit []byte) (s string, ok bool) {
804		if err := json.Unmarshal(lit, &s); err != nil {
805			return "", false
806		}
807		return s, true
808	}
809	
810	// badEscape 描述一处不能组成完整字符的 \uXXXX 转义。
811	type badEscape struct {
812		escape string // 原文中的转义序列，如 \uD800
813		detail string // 具体问题（孤立高代理项/孤立低代理项）
814	}
815	
816	// jsonStringEnd 返回从 raw[i]（必须是 '"'）开始的字符串字面量结束位置
817	// （右引号之后的下标）；未终止时返回 len(raw)。
818	func jsonStringEnd(raw []byte, i int) int {
819		j := i + 1
820		for j < len(raw) {
821			switch raw[j] {
822			case '\\':
823				j += 2
824			case '"':
825				return j + 1
826			default:
827				j++
828			}
829		}
830		return len(raw)
831	}
832	
833	// findBadUnicodeEscape 在字符串内容（不含引号）中查找第一处不能组成完整
834	// 字符的 \uXXXX 转义；没有则返回 nil。反斜杠本身的转义（\\）先于 \u 判定，
835	// 因此 "\\uD800" 只是普通文本。非法的 \u 写法（非 4 位十六进制）属于 JSON
836	// 语法错误，不在此报告。
837	func findBadUnicodeEscape(content []byte) *badEscape {
838		j := 0
839		for j < len(content) {
840			if content[j] != '\\' {
841				j++
842				continue
843			}
844			if j+1 >= len(content) {
845				break
846			}
847			if content[j+1] != 'u' {
848				j += 2
849				continue
850			}
851			if j+6 > len(content) || !isHex4(content[j+2:j+6]) {
852				j += 2
853				continue
854			}
855			cp := hexVal4(content[j+2 : j+6])
856			switch {
857			case cp >= 0xD800 && cp <= 0xDBFF:
858				// 高代理项只有紧跟一个低代理项转义才组成完整字符。
859				if j+12 <= len(content) && content[j+6] == '\\' && content[j+7] == 'u' &&
860					isHex4(content[j+8:j+12]) {
861					if lo := hexVal4(content[j+8 : j+12]); lo >= 0xDC00 && lo <= 0xDFFF {
862						j += 12
863						continue
864					}
865				}
866				return &badEscape{
867					escape: string(content[j : j+6]),
868					detail: "high surrogate is not followed by a low surrogate",
869				}
870			case cp >= 0xDC00 && cp <= 0xDFFF:
871				return &badEscape{
872					escape: string(content[j : j+6]),
873					detail: "low surrogate is not preceded by a high surrogate",
874				}
875			}
876			j += 6
877		}
878		return nil
879	}
880	
881	// isJSONStructural 报告 b 是否为 JSON 结构字符或空白（标量值的边界）。
882	func isJSONStructural(b byte) bool {
883		switch b {
884		case ' ', '\t', '\n', '\r', '{', '}', '[', ']', ':', ',', '"':
885			return true
886		}
887		return false
888	}
889	
890	// isHex4 报告 b 是否恰好为 4 个十六进制数字。
891	func isHex4(b []byte) bool {
892		if len(b) != 4 {
893			return false
894		}
895		for _, c := range b {
896			if !isHexDigit(c) {
897				return false
898			}
899		}
900		return true
901	}
902	
903	func isHexDigit(c byte) bool {
904		return ('0' <= c && c <= '9') || ('a' <= c && c <= 'f') || ('A' <= c && c <= 'F')
905	}
906	
907	// hexVal4 把 4 个十六进制数字解析为码点值；调用前须先经 isHex4 校验。
908	func hexVal4(b []byte) int {
909		v := 0
910		for _, c := range b {
911			v <<= 4
912			switch {
913			case '0' <= c && c <= '9':
914				v |= int(c - '0')
915			case 'a' <= c && c <= 'f':
916				v |= int(c-'a') + 10
917			default: // 'A' <= c && c <= 'F'
918				v |= int(c-'A') + 10
919			}
920		}
921		return v
922	}
923	
924	func parseFlag(raw any, index int) (Flag, error) {
925		loc := fmt.Sprintf("config.flags[%d]", index)
926		obj, ok := raw.(map[string]any)
927		if !ok {
928			return Flag{}, fmt.Errorf("%s: flag must be a JSON object", loc)
929		}
930		key, err := requireNonEmptyString(obj, "key", loc)
931		if err != nil {
932			return Flag{}, err
933		}
934		enabled, err := requireBool(obj, "enabled", loc)
935		if err != nil {
936			return Flag{}, err
937		}
938		def, err := requireBool(obj, "default", loc)
939		if err != nil {
940			return Flag{}, err
941		}
942		rulesArr, err := requireArrayField(obj, "rules", loc)
943		if err != nil {
944			return Flag{}, err
945		}
946		flag := Flag{Key: key, Enabled: enabled, Default: def}
947		seenRules := map[string]int{}
948		for ri, rv := range rulesArr {
949			rule, err := parseRule(rv, index, ri)
950			if err != nil {
951				return Flag{}, err
952			}
953			if prev, dup := seenRules[rule.ID]; dup {
954				return Flag{}, fmt.Errorf("%s.rules[%d].id: duplicate rule id %q (first at rules[%d])", loc, ri, rule.ID, prev)
955			}
956			seenRules[rule.ID] = ri
957			flag.Rules = append(flag.Rules, rule)
958		}
959		return flag, nil
960	}
961	
962	func parseRule(raw any, flagIndex, ruleIndex int) (Rule, error) {
963		loc := fmt.Sprintf("config.flags[%d].rules[%d]", flagIndex, ruleIndex)
964		obj, ok := raw.(map[string]any)
965		if !ok {
966			return Rule{}, fmt.Errorf("%s: rule must be a JSON object", loc)
967		}
968		id, err := requireNonEmptyString(obj, "id", loc)
969		if err != nil {
970			return Rule{}, err
971		}
972		value, err := requireBool(obj, "value", loc)
973		if err != nil {
974			return Rule{}, err
975		}
976		condsArr, err := requireArrayField(obj, "conditions", loc)
977		if err != nil {
978			return Rule{}, err
979		}
980		if len(condsArr) == 0 {
981			return Rule{}, fmt.Errorf("%s.conditions: must contain at least one condition", loc)
982		}
983		rule := Rule{ID: id, Value: value}
984		for ci, cv := range condsArr {
985			cond, err := parseCondition(cv, flagIndex, ruleIndex, ci)
986			if err != nil {
987				return Rule{}, err
988			}
989			rule.Conditions = append(rule.Conditions, cond)
990		}
991		return rule, nil
992	}
993	
994	func parseCondition(raw any, flagIndex, ruleIndex, condIndex int) (Condition, error) {
995		loc := fmt.Sprintf("config.flags[%d].rules[%d].conditions[%d]", flagIndex, ruleIndex, condIndex)
996		obj, ok := raw.(map[string]any)
997		if !ok {
998			return Condition{}, fmt.Errorf("%s: condition must be a JSON object", loc)
999		}
1000		attribute, err := requireNonEmptyString(obj, "attribute", loc)
1001		if err != nil {
1002			return Condition{}, err
1003		}
1004		op, err := requireNonEmptyString(obj, "op", loc)
1005		if err != nil {
1006			return Condition{}, err
1007		}
1008		valueField, err := requireField(obj, "value", loc)
1009		if err != nil {
1010			return Condition{}, err
1011		}
1012		cond := Condition{Attribute: attribute, Op: op}
1013		switch op {
1014		case "eq":
1015			s, ok := valueField.(string)
1016			if !ok {
1017				return Condition{}, fmt.Errorf("%s.value: must be a string when op is %q", loc, op)
1018			}
1019			cond.strVal = s
1020		case "in":
1021			arr, ok := valueField.([]any)
1022			if !ok {
1023				return Condition{}, fmt.Errorf("%s.value: must be an array when op is %q", loc, op)
1024			}
1025			if len(arr) == 0 {
1026				return Condition{}, fmt.Errorf("%s.value: in-list must contain at least one item", loc)
1027			}
1028			for ii, item := range arr {
1029				s, ok := item.(string)
1030				if !ok {
1031					return Condition{}, fmt.Errorf("%s.value[%d]: must be a string", loc, ii)
1032				}
1033				cond.inVal = append(cond.inVal, s)
1034			}
1035		default:
1036			return Condition{}, fmt.Errorf("%s.op: unknown operator %q (allowed: eq, in)", loc, op)
1037		}
1038		return cond, nil
1039	}
1040	
1041	func requireField(obj map[string]any, name, loc string) (any, error) {
1042		v, ok := obj[name]
1043		if !ok {
1044			return nil, fmt.Errorf("%s: field is required", appendFieldPath(loc, name))
1045		}
1046		if v == nil {
1047			return nil, fmt.Errorf("%s: must not be null", appendFieldPath(loc, name))
1048		}
1049		return v, nil
1050	}
1051	
1052	func requireArrayField(obj map[string]any, name, loc string) ([]any, error) {
1053		v, err := requireField(obj, name, loc)
1054		if err != nil {
1055			return nil, err
1056		}
1057		arr, ok := v.([]any)
1058		if !ok {
1059			return nil, fmt.Errorf("%s: must be an array", appendFieldPath(loc, name))
1060		}
1061		return arr, nil
1062	}
1063	
1064	func requireNonEmptyString(obj map[string]any, name, loc string) (string, error) {
1065		v, err := requireField(obj, name, loc)
1066		if err != nil {
1067			return "", err
1068		}
1069		s, ok := v.(string)
1070		if !ok {
1071			return "", fmt.Errorf("%s: must be a string", appendFieldPath(loc, name))
1072		}
1073		if s == "" {
1074			return "", fmt.Errorf("%s: must not be empty", appendFieldPath(loc, name))
1075		}
1076		return s, nil
1077	}
1078	
1079	func requireBool(obj map[string]any, name, loc string) (bool, error) {
1080		v, err := requireField(obj, name, loc)
1081		if err != nil {
1082			return false, err
1083		}
1084		b, ok := v.(bool)
1085		if !ok {
1086			return false, fmt.Errorf("%s: must be a boolean", appendFieldPath(loc, name))
1087		}
1088		return b, nil
1089	}
