762	// evalSuccess 运行 evaluate 并要求成功：退出码 0、stderr 为空、stdout 恰好是
763	// 一行 JSON 对象。返回解码后的字段与 stdout 原文（供逐字节比较）。
764	func evalSuccess(t *testing.T, h *harness, key string) (map[string]any, string) {
765		t.Helper()
766		var stdout, stderr bytes.Buffer
767		if code := run(h.evalArgs(key), &stdout, &stderr); code != 0 {
768			t.Fatalf("key %q: exit=%d stderr=%q", key, code, stderr.String())
769		}
770		if stderr.Len() != 0 {
771			t.Fatalf("key %q: stderr must be empty on success: %q", key, stderr.String())
772		}
773		out := stdout.String()
774		if strings.Count(strings.TrimSpace(out), "\n") != 0 {
775			t.Fatalf("key %q: stdout must contain exactly one JSON object line: %q", key, out)
776		}
777		var got map[string]any
778		if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
779			t.Fatalf("key %q: stdout is not a single JSON object: %q (%v)", key, out, err)
780		}
781		return got, out
782	}
