1129	// --- evaluate 对 in 条件精确成员判断的端到端回归保障 ---------------------------
1130	//
1131	// 下列常量用 Go 原始字符串拼接出 JSON 转义文本（与本文件既有写法一致），确保
1132	// “转义写法”和“直接字符”在源码层面就是两个不同的输入。
1133	const (
1134		// cliEscEA 是 U+00E9 的 JSON 转义写法；cliEscCB 是 e 加组合附加符号 U+0301
1135		// 的转义写法（与预组合字符不同）；cliEscGR 是 U+1F600 的一对代理项转义；
1136		// cliEscTier 是属性名 tier 四个字母各自转义后的写法。
1137		cliEscEA   = (`\u` + `00E9`)
1138		cliEscCB   = (`e\u` + `0301`)
1139		cliEscGR   = (`\u` + `D83D`) + (`\u` + `DE00`)
1140		cliEscTier = (`\u` + `0074`) + (`\u` + `0069`) + (`\u` + `0065`) + (`\u` + `0072`)
1141		// cliLitEA 是 JSON 里“已转义的反斜杠后接 u00E9”的普通文本（两个反斜杠
1142		// 后接 u00E9），解码后只是六个字面字符，不再是 Unicode 转义。
1143		cliLitEA = (`\` + `\` + `u00E9`)
1144	)
1145	
1146	// cliInListConfig 拼出只有一个启用开关、一条 in 规则（id=r1、value=true、
1147	// default=false）的配置；listJSON 是完整的候选值数组文本。
1148	func cliInListConfig(listJSON string) string {
1149		return `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[` +
1150			`{"id":"r1","value":true,"conditions":[` +
1151			`{"attribute":"tier","op":"in","value":` + listJSON + `}]}]}]}`
1152	}
