1474	// rulesOf 从解释对象中按顺序取出每条规则的 (id, match)。
1475	func rulesOf(t *testing.T, got map[string]any) []map[string]any {
1476		t.Helper()
1477		exp, ok := got["explanation"].(map[string]any)
1478		if !ok {
1479			t.Fatalf("missing explanation object: %v", got)
1480		}
1481		rules, ok := exp["rules"].([]any)
1482		if !ok {
1483			t.Fatalf("explanation.rules must be an array: %v", exp)
1484		}
1485		res := make([]map[string]any, 0, len(rules))
1486		for _, r0 := range rules {
1487			res = append(res, r0.(map[string]any))
1488		}
1489		return res
1490	}
