package main

import (
	"fmt"

	"github.com/gzhysuiioo/payflow-settlement/payflow"
)

func main() {
	// 第二个开关 key 用 é 转义，且字段顺序重排（rules 在前），缺 default
	s1 := `{"flags":[
		{"key":"café","enabled":true,"default":false,"rules":[
			{"id":"r1","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"pro"}]}]},
		{"rules":[{"conditions":[{"value":["eu",5],"op":"in","attribute":"region"}],"value":false,"id":"r2"}],"enabled":true,"key":"café"}]}`
	if _, err := payflow.ParseConfig([]byte(s1)); err != nil {
		fmt.Println("esc/reorder stage1:", err)
	}
	// 补齐 default（放在最前），仍有列表类型错
	s2 := `{"flags":[
		{"key":"café","enabled":true,"default":false,"rules":[
			{"id":"r1","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"pro"}]}]},
		{"default":false,"rules":[{"conditions":[{"value":["eu",5],"op":"in","attribute":"region"}],"value":false,"id":"r2"}],"enabled":true,"key":"café"}]}`
	if _, err := payflow.ParseConfig([]byte(s2)); err != nil {
		fmt.Println("esc/reorder stage2:", err)
	}
	// 修正列表，只剩重名
	s3 := `{"flags":[
		{"key":"café","enabled":true,"default":false,"rules":[
			{"id":"r1","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"pro"}]}]},
		{"default":false,"rules":[{"conditions":[{"value":["eu","cn"],"op":"in","attribute":"region"}],"value":false,"id":"r2"}],"enabled":true,"key":"café"}]}`
	if _, err := payflow.ParseConfig([]byte(s3)); err != nil {
		fmt.Println("esc/reorder stage3:", err)
	}
	// 全部修正后身份
	s4 := `{"flags":[
		{"key":"café","enabled":true,"default":false,"rules":[
			{"id":"r1","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"pro"}]}]},
		{"default":true,"rules":[{"conditions":[{"value":["eu","cn"],"op":"in","attribute":"region"}],"value":false,"id":"r2"}],"enabled":true,"key":"beta"}]}`
	cfg, err := payflow.ParseConfig([]byte(s4))
	if err != nil {
		fmt.Println("stage4:", err)
		return
	}
	ctx, _ := payflow.ParseContext([]byte(`{"plan":"pro"}`))
	f := cfg.Find("café")
	fmt.Printf("Find café: default=%v, rules=%d, eval(plan=pro)=%+v\n", f.Default, len(f.Rules), f.Evaluate(ctx))
	ctx2, _ := payflow.ParseContext([]byte(`{"region":"eu"}`))
	b := cfg.Find("beta")
	fmt.Printf("Find beta: default=%v, eval(region=eu)=%+v\n", b.Default, b.Evaluate(ctx2))
}
EOF
go run ./cmd/tmpcheck; rm -rf /opt/gsb-fleet/workspaces/inst-36/A/task036/cmd/tmpcheck

